var t=`0946-tonkatsu`;var n=`world-0946`;var i=`JP`;var s=`east-asia`;var o=4;var r=39;var l={en:`Tonkatsu`,ua:`Тонкацу`};var d={en:`Tonkatsu is a Japan dish made with pork loin, all-purpose flour, chicken egg, panko breadcrumbs. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Тонкацу, страва кухні країни Японія. Основні складники: свиняча корейка, пшеничне борошно універсальне, куряче яйце, панко. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var u=[{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:12,i:[[`pork-loin`,720,`g`],[`all-purpose-flour`,95,`g`],[`chicken-egg`,2,`pcs`],[`panko-breadcrumbs`,230,`g`],[`table-salt`,null,`to_taste`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 17 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 17 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:17,i:[[`canola-oil`,800,`ml`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:7,i:[[`white-cabbage`,290,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`tonkatsu-sauce`,130,`g`],[`lemon`,1,`pcs`]]}];var h={slug:t,id:n,country:`JP`,region:s,servings:4,minutes:39,title:l,text:d,steps:u};export{i as country,h as default,n as id,r as minutes,s as region,o as servings,t as slug,u as steps,d as text,l as title};